// Brute-force TSP (exact) — fix city 0 as start, try every permutation.
function tsp(dist) {
  const n = dist.length;
  const cities = [];
  for (let i = 1; i < n; i++) cities.push(i);
  let best = Infinity;
  const permute = (arr, start) => {
    if (start === arr.length) {
      let cost = dist[0][arr[0]];
      for (let i = 0; i < arr.length - 1; i++) cost += dist[arr[i]][arr[i + 1]];
      cost += dist[arr[arr.length - 1]][0];
      best = Math.min(best, cost);
      return;
    }
    for (let i = start; i < arr.length; i++) {
      [arr[start], arr[i]] = [arr[i], arr[start]];
      permute(arr, start + 1);
      [arr[start], arr[i]] = [arr[i], arr[start]];
    }
  };
  permute(cities, 0);
  return best;
}

