import java.util.*;

public class TravelingSalesman {
    private int n;
    private int[][] dist;
    private int[][] dp;
    private int[][] par;
    private static final int INF = Integer.MAX_VALUE / 2;

    public TravelingSalesman(int[][] distMatrix) {
        this.n = distMatrix.length;
        this.dist = distMatrix;
        this.dp = new int[1 << n][n];
        this.par = new int[1 << n][n];
        for (int[] row : dp) Arrays.fill(row, INF);
        for (int[] row : par) Arrays.fill(row, -1);
    }

    // Held-Karp DP: O(n^2 * 2^n) time, O(n * 2^n) space
    public int solve() {
        int FULL = (1 << n) - 1;
        dp[1][0] = 0;  // start at city 0, only city 0 visited

        for (int mask = 1; mask <= FULL; mask++) {
            for (int u = 0; u < n; u++) {
                if ((mask & (1 << u)) == 0) continue;
                if (dp[mask][u] == INF) continue;
                for (int v = 0; v < n; v++) {
                    if ((mask & (1 << v)) != 0) continue;
                    int newMask = mask | (1 << v);
                    int newCost = dp[mask][u] + dist[u][v];
                    if (newCost < dp[newMask][v]) {
                        dp[newMask][v] = newCost;
                        par[newMask][v] = u;
                    }
                }
            }
        }

        // Find minimum cost to complete the tour
        int minCost = INF, lastCity = -1;
        for (int u = 1; u < n; u++) {
            if (dp[FULL][u] == INF) continue;
            int cost = dp[FULL][u] + dist[u][0];
            if (cost < minCost) { minCost = cost; lastCity = u; }
        }

        // Reconstruct path
        List<Integer> path = new ArrayList<>();
        int mask = FULL, cur = lastCity;
        while (cur != -1) {
            path.add(cur);
            int prev = par[mask][cur];
            mask ^= (1 << cur);
            cur = prev;
        }
        Collections.reverse(path);
        path.add(0);  // return to start

        System.out.println("Optimal tour: " + path);
        System.out.println("Minimum cost: " + minCost);
        return minCost;
    }

    public static void main(String[] args) {
        int[][] dist = {
            {0, 10, 15, 20},
            {10, 0, 35, 25},
            {15, 35, 0, 30},
            {20, 25, 30, 0}
        };
        TravelingSalesman tsp = new TravelingSalesman(dist);
        tsp.solve();  // tour [0,1,3,2,0], cost 80
    }
}

