#define MAXN 20
#define INF (INT_MAX / 2)
int n;
int dist[MAXN][MAXN];
int dp[1 << MAXN][MAXN];
int par[1 << MAXN][MAXN];

int solveTSP() {
    int FULL = (1 << n) - 1;

    for (int i = 0; i <= FULL; i++) for (int j = 0; j < n; j++) {
        dp[i][j] = INF;
        par[i][j] = -1;
    }

    dp[1][0] = 0;
    // start at city 0
    for (int mask = 1; mask <= FULL; mask++) {
        for (int u = 0; u < n; u++) {
            if (!(mask & (1 << u))) continue;
            if (dp[mask][u] == INF) continue;
            for (int v = 0; v < n; v++) {
                if (mask & (1 << v)) continue;
                int nm = mask | (1 << v);
                int nc = dp[mask][u] + dist[u][v];
                if (nc < dp[nm][v]) {
                    dp[nm][v] = nc;
                    par[nm][v] = u;
                }
            }
        }
    }

    int minCost = INF, lastCity = -1;
    for (int u = 1; u < n; u++) {
        if (dp[FULL][u] == INF) continue;
        int cost = dp[FULL][u] + dist[u][0];
        if (cost < minCost) {
            minCost = cost;
            lastCity = u;
        }
    }

    // Reconstruct path
    int path[MAXN], len = 0;
    int mask = FULL, cur = lastCity;
    while (cur != -1) {
        path[len++] = cur;
        int prev = par[mask][cur];
        mask ^= (1 << cur);
        cur = prev;
    }
    printf("Optimal tour: 0");
    for (int i = len - 1; i >= 0; i--) printf(" -> %d", path[i]);
    printf(" -> 0\nMinimum cost: %d\n", minCost);
    return minCost;
}

int main() {
    int d[4][4] = { {
        0, 10, 15, 20
    }, {10, 0, 35, 25}, {15, 35, 0, 30}, {20, 25, 30, 0}};
    n = 4;
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) dist[i][j] = d[i][j];
    solveTSP();
    // 0->1->3->2->0, cost 80
    return 0;
}

