using namespace std;

class TravelingSalesman {
    int n;
    vector<vector<int>> dist, dp, par;
    const int INF = INT_MAX / 2;

    public:
    TravelingSalesman(vector<vector<int>>& d) : n(d.size()), dist(d), dp(1 << d.size(), vector<int>(d.size(), INT_MAX/2)), par(1 << d.size(), vector<int>(d.size(), -1)) {}

    int solve() {
        int FULL = (1 << n) - 1;
        dp[1][0] = 0;

        for (int mask = 1; mask <= FULL; mask++) {
            for (int u = 0; u < n; u++) {
                if (!(mask & (1<<u)) || dp[mask][u] == INF) continue;
                for (int v = 0; v < n; v++) {
                    if (mask & (1<<v)) continue;
                    int nm = mask | (1<<v);
                    int nc = dp[mask][u] + dist[u][v];
                    if (nc < dp[nm][v]) {
                        dp[nm][v] = nc;
                        par[nm][v] = u;
                    }
                }
            }
        }

        int minCost = INF, last = -1;
        for (int u = 1; u < n; u++) {
            int c = dp[FULL][u] + dist[u][0];
            if (dp[FULL][u] != INF && c < minCost) {
                minCost = c;
                last = u;
            }
        }

        // Reconstruct path
        vector<int> path;
        int mask = FULL, cur = last;
        while (cur != -1) {
            path.push_back(cur);
            int prev = par[mask][cur];
            mask ^= (1 << cur);
            cur = prev;
        }
        reverse(path.begin(), path.end());

        cout << "Optimal tour: 0";
        for (int city : path) cout << " -> " << city;
        cout << " -> 0\nMinimum cost: " << minCost << endl;
        return minCost;
    }
};

int main() {
    vector<vector<int>> d = { {
        0, 10, 15, 20
    }, {10, 0, 35, 25}, {15, 35, 0, 30}, {20, 25, 30, 0}};
    TravelingSalesman tsp(d);
    tsp.solve();
    // 0->1->3->2->0, cost 80
    return 0;
}

