def tsp(dist):
    n = len(dist)
    memo = {}
    def solve(mask, pos):
        if mask == (1 << n) - 1:
            return dist[pos][0]
        if (mask, pos) in memo:
            return memo[(mask, pos)]
        best = float('inf')
        for nxt in range(n):
            if not mask & (1 << nxt):
                best = min(best, dist[pos][nxt] + solve(mask | (1 << nxt), nxt))
        memo[(mask, pos)] = best
        return best
    return solve(1, 0)

